/// Serverless provisioned concurrency bypass
std::vector<Finding> scan_serverless_provisioned_concurrency_bypas(const Config &, HttpClient &http,
                                       const CrawlResult &crawl) {
  std::vector<Finding> findings;
  if (crawl.urls.empty()) return findings;
  std::string base = base_url_from(crawl.urls[0]);

  // Serverless provisioned concurrency bypass
  auto resp = http.get(base + "/admin");
  if (resp.status_code == 403 || resp.status_code == 401) {
    // Try bypass
    auto bypass = http.get(base + "/admin", {{"X-Original-URL", "/admin"}});
    if (bypass.status_code == 200 && bypass.body.size() > 200 &&
        bypass.body.find("{") == 0) {
      findings.push_back(Finding{"Serverless provisioned concurrency bypass", "critical", base + "/admin",
                          "Access control bypass successful",
                          "", "X-Original-URL", bypass.body.substr(0, 150)});
    }
  }

  return findings;
}

